for (const override of productionTimelineOverrides) {
  const existingIndex = plantRecipeDrafts.findIndex(
    (draft) => draft.plantName === override.plantName
  );

  if (existingIndex >= 0) {
    plantRecipeDrafts.splice(existingIndex, 1, override);
  } else {
    plantRecipeDrafts.push(override);
  }
}

function rangeDays(start: number, end: number) {
  return Array.from({ length: end - start + 1 }, (_, index) => start + index);
}
